  var dataVal = baseRev[input.charAt(0)];
  var dataPos = 32;
  var dataIdx = 1;
  function readBits(maxpower) {
    var bits = 0;
    var power = 1;
    while (power != maxpower) {
      var resb = dataVal & dataPos;
      dataPos >>= 1;
      if (dataPos == 0) {
        dataPos = 32;
        dataVal = baseRev[input.charAt(dataIdx++)];
      }
      bits |= (resb > 0 ? 1 : 0) * power;
      power <<= 1;
