  var next = readBits(4);
  if (next == 0) {
    c = String.fromCharCode(readBits(256));
  } else if (next == 1) {
    c = String.fromCharCode(readBits(65536));
  } else if (next == 2) {
    return "";
  }
  dictionary[3] = c;
  var w = c;
  result.push(c);
  while (true) {
    if (dataIdx > length) return "";
