    if (cc == 0) {
      dictionary[dictSize++] = String.fromCharCode(readBits(256));
      cc = dictSize - 1;
      enlargeIn--;
    } else if (cc == 1) {
      dictionary[dictSize++] = String.fromCharCode(readBits(65536));
      cc = dictSize - 1;
      enlargeIn--;
    } else if (cc == 2) {
      return result.join("");
    }
    if (enlargeIn == 0) {
      enlargeIn = 1 << numBits;
      numBits++;
    }
    var entry;
    if (dictionary[cc]) {
      entry = dictionary[cc];
    } else if (cc === dictSize) {
      entry = w + w.charAt(0);
    } else {
      return "";
    }
    result.push(entry);
    dictionary[dictSize++] = w + entry.charAt(0);
    enlargeIn--;
    w = entry;
    if (enlargeIn == 0) {
      enlargeIn = 1 << numBits;
      numBits++;
